import "server-only";
import { safeLog } from "@/lib/observability";
import { db } from "@/lib/db";
import { applyFreeCampaignPolicy } from "@/lib/campaign-policy";
import { withUsageTransaction } from "@/lib/usage-ledger";

// Scheduled maintenance runs this each minute. Dispatch and claims also check access directly.
export async function sweepSubscriptionLifecycle() {
  let cursor: string | undefined;
  let failed = 0;
  for (;;) {
    const result = await sweepSubscriptionPage(cursor);
    failed += result.failed;
    cursor = result.cursor ?? undefined;
    if (!cursor) break;
  }
  if (failed) throw new Error("SUBSCRIPTION_LIFECYCLE_INCOMPLETE");
}

async function sweepSubscriptionPage(cursor: string | undefined) {
  const owners = await db.user.findMany({
    where: {
      deletionRequestedAt: null,
      ...(cursor ? { id: { gt: cursor } } : {}),
      campaigns: {
        some: {
          sends: { some: { status: "QUEUED", deliveryState: "READY" } },
        },
      },
    },
    select: { id: true },
    orderBy: { id: "asc" },
    take: 50,
  });
  let failed = 0;
  for (const owner of owners) {
    try {
      await withUsageTransaction(db, owner.id, (locked) =>
        applyFreeCampaignPolicy(locked),
      );
    } catch {
      failed++;
    }
  }
  const result = {
    cursor: owners.length === 50 ? owners.at(-1)!.id : null,
    failed,
  };
  if (failed)
    safeLog("error", "lifecycle", {
      code: "OWNER_RETRY_PENDING",
      count: failed,
    });
  return result;
}
